    "pairing": "भोजन के बाद, रात में, या पानी की जगह। जौ और ब्राउन राइस साल भर; भारी खाने के बाद कैसिया और बर्डॉक; मिठाइयों के साथ और सोने से पहले हर्बल चाय।",
    "brewTip": "उबलते पानी में पाँच मिनट; जड़ों के लिए 10 मिनट। सुगंध बनाए रखने के लिए फूलों को ढक्कन के नीचे भिगोएँ। रूइबोस दूध के साथ अच्छी लगती है।",
    "keep": "भुना अनाज जल्दी सुगंध खोता है: उसे थोड़ी मात्रा में, ठंडा, 3–6 महीनों तक रखें; फूल और पत्तियाँ सीलबंद करके 12 महीनों तक।",
    "keywords": "रोज़मर्रा की चाय जौ ब्राउन राइस कुट्टू कॉर्न सिल्क कैसिया बर्डॉक रूइबोस माटे डैंडेलियन कैफीन मुक्त हर्बल चाय कैमोमाइल पेपरमिंट लैवेंडर लेमनग्रास गुलदाउदी हिबिस्कस"
